WITH valid_departments AS (SELECT * FROM departments WHERE location IN ('Tokyo', 'Chiang Mai', 'Berlin') AND dept_name IN ('Legal', 'Sales', 'Marketing')), Summary AS (SELECT dept_name, ROUND(AVG(budget), 2) avg_budget, COUNT(CASE WHEN location = 'London' THEN 1 END) london_count FROM valid_departments GROUP BY dept_name) SELECT * FROM Summary ORDER BY london_count DESC, avg_budget DESC;
